{"files":[{"content":"/* Cloud Cargo core: deterministic and intentionally DOM-free. */
(function () {
  'use strict';
  function rng(seed) { var s = (seed >>> 0) || 1; return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; }; }
  function shuffle(a, r) { for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; } return a; }
  function makeBoard(state) {
    var stage = state.stage, count = 4 + stage, bayCount = stage === 0 ? 2 : 3;
    var r = rng((state.seed + 0x9e3779b9 * (stage + 1)) >>> 0), cards = [], groups = [], i;
    for (i = 0; i < bayCount; i++) groups.push([]);
    /* Every generated board begins with a valid, concealed partition. */
    for (i = 0; i < count; i++) {
      var card = { mass: 1 + Math.floor(r() * 5), energy: stage ? Math.floor(r() * 4) : 0, bay: -1 };
      cards.push(card); groups[i % bayCount].push(card);
    }
    shuffle(cards, r);
    var bays = groups.map(function (g) {
      var m = 0, e = 0; g.forEach(function (c) { m += c.mass; e += c.energy; });
      return { mass: m, energy: stage ? e : null };
    });
    shuffle(bays, r);
    state.cards = cards; state.bays = bays; state.selectedCard = 0; state.focus = 0;
    state.validTicks = 0; state.dispatchTicks = 0; state.message = 'Choose a crate, then choose a bay.';
  }
  function totals(s, index) {
    var m = 0, e = 0; s.cards.forEach(function (c) { if (c.bay === index) { m += c.mass; e += c.energy; } }); return { mass: m, energy: e };
  }
  function exact(s) {
    if (s.cards.some(function (c) { return c.bay < 0; })) return false;
    for (var i = 0; i < s.bays.length; i++) { var t = totals(s, i), b = s.bays[i]; if (t.mass !== b.mass || (b.energy !== null && t.energy !== b.energy)) return false; }
    return true;
  }
  function activate(s, focus) {
    if (focus < s.cards.length) { s.selectedCard = focus; s.focus = focus; s.message = 'Crate selected — choose a bay.'; return; }
    var bay = focus - s.cards.length;
    if (bay >= 0 && bay < s.bays.length && s.selectedCard >= 0) {
      var card = s.cards[s.selectedCard];
      if (card.bay !== bay) { card.bay = bay; s.assignments++; s.interactions++; }
      s.focus = focus; s.message = 'Assigned to bay ' + String.fromCharCode(65 + bay) + '.';
    }
  }
  function pointerFocus(s, p) {
    if (!p) return -1;
    if (p.y >= .08 && p.y <= .39) { var b = Math.floor(p.x * s.bays.length); return b >= 0 && b < s.bays.length ? s.cards.length + b : -1; }
    if (p.y >= .43 && p.y <= .92) { var row = p.y < .70 ? 0 : 1, col = Math.floor(p.x * 3), n = row * 3 + col; return n >= 0 && n < s.cards.length ? n : -1; }
    return -1;
  }
  var core = {
    create: function (seed) {
      var s = { seed: seed >>> 0, tick: 0, stage: 0, score: 0, assignments: 0, interactions: 0, focus: 0, selectedCard: 0, cards: [], bays: [], validTicks: 0, dispatchTicks: 0, message: '', terminal: false, lastMove: 0 };
      makeBoard(s); return s;
    },
    step: function (s, input) {
      input = input || {}; if (s.terminal) return s; s.tick++;
      if (s.dispatchTicks > 0) {
        s.dispatchTicks--;
        if (s.dispatchTicks === 0 && s.stage < 3) makeBoard(s);
        if (s.stage === 3 && s.tick >= 900 && s.dispatchTicks === 0) s.terminal = true;
        return s;
      }
      if (s.tick >= 3000) { s.terminal = true; s.message = 'Time is up — refine the cargo partition.'; return s; }
      var n = s.cards.length + s.bays.length;
      if (input.pointer) { var pf = pointerFocus(s, input.pointer); if (pf >= 0) { s.focus = pf; activate(s, pf); } }
      else {
        var dx = input.x || 0;
        if (dx && s.tick - s.lastMove >= 8) { s.focus = (s.focus + (dx > 0 ? 1 : -1) + n) % n; s.lastMove = s.tick; s.interactions++; }
        if (input.action) { activate(s, s.focus); s.interactions++; }
      }
      if (exact(s)) {
        s.validTicks++;
        s.message = 'Manifest verified…';
        if (s.validTicks >= 30) {
          s.stage++; s.score += 180 + Math.max(0, Math.floor((3000 - s.tick) / 20)) + Math.max(0, 20 - s.assignments);
          s.dispatchTicks = 75; s.message = s.stage === 3 ? 'Expedition fleet departing!' : 'Airship dispatched!';
        }
      } else s.validTicks = 0;
      return s;
    },
    observe: function (s) { return { tick: s.tick, score: s.score, progress: Math.min(100, Math.floor(s.tick * 100 / 3000)), interactions: s.interactions, entities: s.cards.length + s.bays.length + 4 }; },
    terminal: function (s) { return !!s.terminal; }
  };
  window.CloudCargoCore = core;
}());
