  setReduced(media); if (media.addEventListener) media.addEventListener('change', setReduced); else media.addListener(setReduced);
  function copy(o) { return JSON.parse(JSON.stringify(o)); }
  function appDraw(ctx, snapshot, size) {
    var state = snapshot.state || snapshot;
    var best = Number(snapshot.best || 0), terminal = CloudCargoCore.terminal(state);
    document.querySelector('[data-game-score]').textContent = String(state.score || 0);
    document.querySelector('[data-cargo-best]').textContent = String(best);
    document.querySelector('[data-cargo-goal-progress]').textContent = state.stage + '/3';
    document.querySelector('[data-game-progress]').textContent = 'ELAPSED ' + Math.min(100, Math.floor(state.tick * 100 / 3000)) + '%';
    var heading = document.querySelector('[data-cargo-result]'), detail = document.querySelector('[data-cargo-result-detail]');
    if (terminal) { heading.hidden = false; detail.hidden = false; heading.textContent = state.stage === 3 ? 'SKYPORT COMPLETE' : 'CARGO INCOMPLETE'; detail.textContent = state.stage === 3 ? '3/3 dispatched · ' + state.assignments + ' assignments · score ' + state.score : state.stage + '/3 dispatched · ' + state.assignments + ' assignments. Try balancing energy after mass.'; }
    else { heading.hidden = true; detail.hidden = true; }
    var width = (size && size.width) || ctx.canvas.width, height = (size && size.height) || ctx.canvas.height;
    CargoPresentation.draw(ctx, copy(snapshot), { width: width, height: height, reducedMotion: reduced });
  }
  fetch('./manifest.json').then(function (r) { return r.json(); }).then(function (metadata) {
    PlayJoltGameKit.create({ core: CloudCargoCore, draw: appDraw, canvas: document.querySelector('[data-game-canvas]'), metadata: metadata });
  }).catch(function (e) { var el = document.querySelector('[data-game-error]'); el.hidden = false; el.textContent = 'Could not prepare local practice: ' + e.message; });
}());
