  function draw(ctx,snapshot,opt) {
    var s=snapshot.state||snapshot, w=opt.width,h=opt.height, cards=s.cards||[], bays=s.bays||[];
    ctx.clearRect(0,0,w,h); ctx.fillStyle='#07172b';ctx.fillRect(0,0,w,h);
