      ctx.strokeStyle='rgba(207,239,230,.24)';ctx.lineWidth=1;rr(ctx,x-cw/2,y,cw,ch,12);ctx.stroke(); if(!c)continue;
      var selected=s.selectedCard===j, focused=s.focus===j;ctx.fillStyle=selected?'#ff805f':'#f3e2b7';rr(ctx,x-cw/2,y,cw,ch,12);ctx.fill();if(focused){ctx.strokeStyle='#76f1da';ctx.lineWidth=3;ctx.stroke();}
      text(ctx,'CRATE '+(j+1),x,y+25,13,'#23364a');text(ctx,'M '+c.mass+'   E '+c.energy,x,y+51,17,'#23364a');text(ctx,c.bay<0?'UNASSIGNED':'BAY '+String.fromCharCode(65+c.bay),x,y+ch-13,12,c.bay<0?'#8c5546':'#17616b');
    }
